#include <bits/stdc++.h>
using namespace std;

void increment(string& s) {
    int i = static_cast<int>(s.size()) - 1;
    while (i >= 0 && s[i] == '9') {
        s[i] = '0';
        --i;
    }
    if (i < 0) {
        s.insert(s.begin(), '1');
    } else {
        ++s[i];
    }
}

bool valid(const string& digits, int length) {
    string current = digits.substr(0, length);
    if (current[0] == '0') return false;

    int pos = 0;
    while (pos < static_cast<int>(digits.size())) {
        if (pos + static_cast<int>(current.size()) > static_cast<int>(digits.size()))
            return false;

        if (digits.compare(pos, current.size(), current) != 0)
            return false;

        pos += current.size();
        if (pos < static_cast<int>(digits.size()))
            increment(current);
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    string digits;
    digits.reserve(N);

    for (int i = 0; i < N; ++i) {
        int d;
        cin >> d;
        digits.push_back(char('0' + d));
    }

    for (int length = 1; length <= N; ++length) {
        if (valid(digits, length)) {
            cout << digits.substr(0, length) << '\n';
            return 0;
        }
    }

    return 0;
}
